const dados = $('Dados').first().json;
const webhookBody = $('Webhook').first().json.body;

let base64 = $json.base64 
          || webhookBody?.data?.message?.base64 
          || webhookBody?.data?.base64 
          || webhookBody?.data?.message?.imageMessage?.base64 
          || '';

base64 = base64.replace(/^data:image\/\w+;base64,/, '').trim();

return [{
  json: {
    caption: dados.caption || '',
    remoteJid: dados.remoteJid,
    instance: dados.instance,
    senderNumber: dados.senderNumber
  },
  binary: {
    data: {
      data: base64,
      mimeType: 'image/jpeg',
      fileName: 'carro_patio.jpg'
    }
  }
}];

const parts = $json.content?.parts || $json.candidates?.[0]?.content?.parts || [];
const textPart = parts.find(p => p.text && !p.thought) || parts[parts.length - 1] || {};
let geminiRaw = textPart.text 
  || (typeof $json.text === 'string' ? $json.text : '') 
  || (typeof $json.output === 'string' ? $json.output : '') 
  || (typeof $json.content === 'string' ? $json.content : '') 
  || '';

geminiRaw = String(geminiRaw).replace(/```json/gi, '').replace(/```/g, '').trim();

let parsed;
try {
  const jsonMatch = geminiRaw.match(/\{[\s\S]*\}/);
  parsed = JSON.parse(jsonMatch ? jsonMatch[0] : geminiRaw);
} catch (e) {
  parsed = {
    placa: null,
    carro: 'Veículo',
    tipoCarro: 'Sedan',
    nome: null,
    telefone: null,
    tipoLavagem: null,
    valor: null,
    formaPagamento: 'A combinar'
  };
}

const dados = $('Dados').first().json;
const caption = String(dados.caption || '').trim();
const captionLower = caption.toLowerCase();

const placa = parsed.placa ? String(parsed.placa).toUpperCase().replace(/[^A-Z0-9]/g, '') : '';
let tipoCarro = parsed.tipoCarro || 'Sedan';
const fullCarText = (tipoCarro + ' ' + (parsed.carro || '')).toLowerCase();

if (/moto|scooter|bis|cg|titan|fan|bros|xre|cb|fazer|lander|yamaha|harley|pcx|nmax/i.test(fullCarText)) {
  tipoCarro = 'Moto';
} else if (/van|sprinter|ducato|master|jumper|boxer|transit|fiorino|kangoo|partner|kombi|topic|daily|hr|bongo|iveco|furgao|furgão|utilitario|utilitário/i.test(fullCarText)) {
  tipoCarro = 'Van';
} else if (/picape|pickup|caminhonete|camionete|hilux|ranger|amarok|s10|toro|strada|saveiro|ram|montana|oroch|l200|frontier/i.test(fullCarText)) {
  tipoCarro = 'Picape';
} else if (/suv|kicks|compass|renegade|tracker|creta|hr-v|hrv|t-cross|tcross|nivus|duster|ecosport|spin|sw4|tiggo|pajero|fastback|pulse/i.test(fullCarText)) {
  tipoCarro = 'SUV';
} else if (/hatch|gol|onix|hb20|palio|uno|argo|mobi|kwid|sandero|fox|polo|up|celta|corsa|fiesta|ka|fit|march|208|c3|a3|golf|yaris/i.test(fullCarText)) {
  tipoCarro = 'Hatch';
} else if (!['Hatch', 'Sedan', 'SUV', 'Picape', 'Van', 'Moto'].includes(tipoCarro)) {
  tipoCarro = 'Sedan';
}

// Verificar nome e se é da oficina Jcar (Jeferson) ANTES do cálculo de valores!
const invalidNames = ['simples', 'ducha', 'completa', 'completo', 'vip', 'motor', 'baixo', 'pix', 'dinheiro', 'debito', 'débito', 'credito', 'crédito', 'cartao', 'cartão', 'null'];
const rawNome = parsed.nome ? String(parsed.nome).trim() : '';
const nomeInformado = rawNome !== '' && !invalidNames.includes(rawNome.toLowerCase()) && !/^\d+$/.test(rawNome);
const telefoneInformado = parsed.telefone && parsed.telefone !== 'null' && String(parsed.telefone).replace(/\D/g, '').length >= 8;
const isJcar = /jeferson|jefferson|jéferson|jcar|\bj car\b/i.test(captionLower) || /jeferson|jefferson|jéferson|jcar/i.test(rawNome);
let nomeFinal = nomeInformado ? rawNome : null;
if (isJcar) {
  nomeFinal = 'Jeferson (Jcar)';
}

// Extrair valor numérico da legenda ou do Gemini
let valorNum = null;
const numMatches = caption.match(/\b(\d{2,3})\b/g);
if (numMatches && numMatches.length > 0) {
  valorNum = parseInt(numMatches[numMatches.length - 1], 10);
} else if (parsed.valor && /^\d+$/.test(String(parsed.valor).trim())) {
  valorNum = parseInt(String(parsed.valor).trim(), 10);
}

const isSuvOrPicape = (tipoCarro === 'SUV' || tipoCarro === 'Picape');
const isHatchOrSedan = (tipoCarro === 'Hatch' || tipoCarro === 'Sedan');
const isMoto = (tipoCarro === 'Moto');

// 1. PRIORIDADE MÁXIMA ABSOLUTA: Verificar se a legenda escreveu explicitamente o nome do serviço!
let servicoExplicito = null;
if (/motor|baixo|chassi|personalizad/i.test(captionLower)) {
  servicoExplicito = 'Lavagem Personalizada (Por baixo e Motor)';
} else if (/\bvip\b|cera|polimento/i.test(captionLower)) {
  servicoExplicito = 'Lavagem VIP';
} else if (/\bducha\b|\bduxinha\b|\bduxa\b/i.test(captionLower)) {
  servicoExplicito = 'Ducha';
} else if (/\bsimples\b|\bsinples\b|\bsimpres\b/i.test(captionLower)) {
  servicoExplicito = 'Simples';
} else if (/complet[ao]|conplet[ao]|complwt[ao]|geral/i.test(captionLower)) {
  servicoExplicito = 'Completa';
}

let tipoLavagem = servicoExplicito || '';
let valorFinal = valorNum !== null ? String(valorNum) : (parsed.valor && parsed.valor !== 'null' ? String(parsed.valor) : 'A combinar');

// REGRA DA OFICINA JCAR (JEFERSON): Tabela fixa Hatch/Sedan 50, SUV/Picape 65 (legenda com prioridade máxima!)
if (isJcar) {
  if (valorNum !== null) {
    valorFinal = String(valorNum);
  } else {
    if (isHatchOrSedan) valorFinal = '50';
    else if (isSuvOrPicape) valorFinal = '65';
    else valorFinal = '65';
  }
  if (!servicoExplicito) tipoLavagem = 'Completa';
} else if (!servicoExplicito) {
  // 2. SOMENTE se o serviço NÃO foi escrito explicitamente na legenda, aplica a Tabela Mental pelo valor!
  if (isMoto) {
    if (valorNum === null) valorFinal = '30';
    tipoLavagem = 'Completa (Moto)';
  } else if (valorNum !== null) {
    if (isHatchOrSedan) {
      if (valorNum === 30) tipoLavagem = 'Simples / Ducha';
      else if (valorNum === 60) tipoLavagem = 'Completa';
      else if (valorNum === 90) tipoLavagem = 'Lavagem VIP';
      else if (valorNum >= 120) tipoLavagem = 'Lavagem Personalizada (Por baixo e Motor)';
    } else if (isSuvOrPicape) {
      if (valorNum === 40) tipoLavagem = 'Simples / Ducha';
      else if (valorNum === 90) tipoLavagem = 'Completa';
      else if (valorNum >= 100 && valorNum <= 120) tipoLavagem = 'Lavagem VIP';
      else if (valorNum > 120) tipoLavagem = 'Lavagem Personalizada (Por baixo e Motor)';
    }
  }
} else if (valorNum === null) {
  // Se escreveu o nome do serviço mas não escreveu o valor, preenche o valor padrão pela Tabela Mental!
  if (isMoto) {
    valorFinal = '30';
  } else if (servicoExplicito === 'Lavagem Personalizada (Por baixo e Motor)') {
    valorFinal = '120';
  } else if (servicoExplicito === 'Lavagem VIP') {
    valorFinal = isSuvOrPicape ? '100' : '90';
  } else if (servicoExplicito === 'Ducha' || servicoExplicito === 'Simples') {
    valorFinal = isSuvOrPicape ? '40' : '30';
  } else if (servicoExplicito === 'Completa') {
    valorFinal = isSuvOrPicape ? '90' : '60';
  }
}

if (!tipoLavagem) {
  tipoLavagem = parsed.tipoLavagem || 'Completa';
}

return [{
  json: {
    placa: placa,
    carro: parsed.carro || 'Veículo',
    tipoCarro: tipoCarro,
    nome: nomeFinal,
    isJcar: isJcar,
    telefone: telefoneInformado ? String(parsed.telefone).trim() : null,
    tipoLavagem: tipoLavagem,
    valor: valorFinal,
    formaPagamento: parsed.formaPagamento || 'A combinar',
    precisaBuscarHistorico: (!nomeInformado || !telefoneInformado) && !!placa,
    senderNumber: dados.senderNumber,
    remoteJid: dados.remoteJid,
    instance: dados.instance
  }
}];

const geminiData = $('Processar Dados do Gemini').first().json;
const rows = $input.all();

let nome = geminiData.nome;
let telefone = geminiData.telefone;
let clienteAntigo = false;
let jaRegistradoHoje = false;
let isJcar = geminiData.isJcar || false;

// Obter a data de hoje no padrão dd/MM (fuso de São Paulo)
const now = new Date();
const spTime = new Date(now.toLocaleString('en-US', { timeZone: 'America/Sao_Paulo' }));
const day = String(spTime.getDate()).padStart(2, '0');
const month = String(spTime.getMonth() + 1).padStart(2, '0');
const dataHoje = day + '/' + month;

if (geminiData.placa) {
  const matches = rows.filter(r => r.json && r.json.Placa && String(r.json.Placa).toUpperCase().replace(/[^A-Z0-9]/g, '') === geminiData.placa);

  // Verificar se essa mesma placa já deu entrada HOJE na planilha
  const matchHoje = matches.find(r => r.json && String(r.json.Data || '').trim() === dataHoje);
  if (matchHoje) {
    jaRegistradoHoje = true;
  }

  const match = matches.length > 0 ? matches[matches.length - 1] : null;
  if (match && match.json) {
    if (!nome && match.json.Nome && match.json.Nome !== 'Cliente Balcão') {
      nome = match.json.Nome;
      clienteAntigo = true;
    }
    if (!telefone && match.json.Telefone && match.json.Telefone !== 'Presencial') {
      telefone = String(match.json.Telefone);
      clienteAntigo = true;
    }
  }
}

if (nome && /jeferson|jefferson|jéferson|jcar/i.test(nome)) {
  isJcar = true;
  nome = 'Jeferson (Jcar)';
  const caption = String($('Dados').first().json.caption || '');
  const hasValorNaLegenda = /\b\d{2,3}\b/.test(caption);
  if (!hasValorNaLegenda) {
    if (geminiData.tipoCarro === 'Hatch' || geminiData.tipoCarro === 'Sedan') {
      geminiData.valor = '50';
    } else if (geminiData.tipoCarro === 'SUV' || geminiData.tipoCarro === 'Picape') {
      geminiData.valor = '65';
    }
  }
}
if (!nome) nome = 'Cliente Balcão';
if (!telefone) telefone = 'Presencial';

return [{
  json: {
    nome: nome,
    telefone: telefone,
    carro: geminiData.carro,
    tipoCarro: geminiData.tipoCarro,
    placa: geminiData.placa || 'Sem placa',
    tipoLavagem: geminiData.tipoLavagem,
    valor: geminiData.valor,
    formaPagamento: geminiData.formaPagamento,
    clienteAntigo: clienteAntigo,
    jaRegistradoHoje: jaRegistradoHoje,
    isJcar: isJcar,
    dataHoje: dataHoje,
    remoteJid: geminiData.remoteJid,
    instance: geminiData.instance
  }
}];

const dados = $('Dados').first().json;
const rows = $input.all();
const bossNumbers = ['5511944724367', '11944724367', '5511989568771', '11989568771'];

function cleanPhone(raw) {
  if (!raw) return '';
  let digits = String(raw).replace(/\D/g, '');
  if (!digits || digits.length < 10) return '';
  if (digits.length === 10 || digits.length === 11) {
    digits = '55' + digits;
  }
  return digits;
}

function isBossPhone(digits) {
  return bossNumbers.some(b => digits.includes(b) || b.includes(digits));
}

const quoted = String(dados.quotedText || '').trim();

// Se o Portuga enviou "ok" solto sem responder/citar a mensagem de nenhum pedido específico
if (!quoted) {
  return [{
    json: {
      encontrado: false,
      msgErroBoss: '⚠️ *Patrão, para não misturar os pedidos:* Por favor, *deslize o dedo para o lado e responda (cite)* a mensagem do pedido que ficou pronto enviando *ok*!\n\nAssim eu sei com 100% de certeza qual cliente devo avisar! 🚗📲',
      bossRemoteJid: dados.remoteJid,
      instance: dados.instance
    }
  }];
}

// O Portuga respondeu a uma mensagem com "ok"
let matchedRow = null;
const placaMatch = quoted.match(/Placa:\s*([A-Z0-9-]{7,8})/i);
const foneMatch = quoted.match(/Telefone:\s*([0-9()+\s-]{8,20})/i);
const quotedPlaca = placaMatch ? placaMatch[1].toUpperCase().replace(/[^A-Z0-9]/g, '') : '';
const quotedFone = foneMatch ? cleanPhone(foneMatch[1]) : '';

// 1. Procurar o carro correspondente na planilha pela placa ou telefone da mensagem citada
for (let i = rows.length - 1; i >= 0; i--) {
  const r = rows[i].json;
  if (!r) continue;
  const rPlaca = String(r.Placa || '').toUpperCase().replace(/[^A-Z0-9]/g, '');
  const rFone = cleanPhone(r.Telefone);
  if ((quotedPlaca && rPlaca === quotedPlaca) || (quotedFone && rFone === quotedFone)) {
    matchedRow = r;
    break;
  }
}

// 2. Se não achou na planilha, mas tem os dados no texto da mensagem citada
if (!matchedRow && (quotedPlaca || quotedFone)) {
  const nomeMatch = quoted.match(/Cliente:\s*([^\n\r]+)/i);
  const carroMatch = quoted.match(/Ve[íi]culo:\s*([^\n\r(—-]+)/i);
  matchedRow = {
    Nome: nomeMatch ? nomeMatch[1].trim() : 'Cliente',
    Telefone: quotedFone || 'Presencial',
    Carro: carroMatch ? carroMatch[1].trim() : 'veículo',
    Placa: quotedPlaca || 'Sem placa',
    'Tipo Lavagem': 'Lavagem'
  };
}

if (!matchedRow) {
  return [{
    json: {
      encontrado: false,
      msgErroBoss: '⚠️ *Patrão:* Não consegui identificar a placa nem o cliente nessa mensagem citada. Por favor, responda diretamente na mensagem de confirmação do pedido dizendo *ok*! 📋',
      bossRemoteJid: dados.remoteJid,
      instance: dados.instance
    }
  }];
}

const foneLimpo = cleanPhone(matchedRow.Telefone);

// Se o cliente for presencial / balcão (sem WhatsApp cadastrado)
if (!foneLimpo || isBossPhone(foneLimpo)) {
  return [{
    json: {
      encontrado: false,
      msgErroBoss: 'ℹ️ *Patrão:* O veículo *' + (matchedRow.Carro || 'Veículo') + '* (Placa: *' + (matchedRow.Placa || '') + '*) foi registrado como *Cliente Balcão / Presencial* (sem WhatsApp cadastrado). Não há cliente para avisar no privado! 🚗✅',
      placa: matchedRow.Placa || '',
      bossRemoteJid: dados.remoteJid,
      instance: dados.instance
    }
  }];
}

return [{
  json: {
    encontrado: true,
    clienteNome: matchedRow.Nome || 'Cliente',
    clienteTelefone: foneLimpo,
    clienteRemoteJid: foneLimpo + '@s.whatsapp.net',
    carro: matchedRow.Carro || 'veículo',
    placa: matchedRow.Placa || 'Sem placa',
    tipoLavagem: matchedRow['Tipo Lavagem'] || 'Lavagem',
    bossRemoteJid: dados.remoteJid,
    instance: dados.instance
  }
}];

