const dados = $input.first().json;
const staticData = $getWorkflowStaticData('global');

if (typeof staticData.botAtivo !== 'boolean') {
  staticData.botAtivo = true;
}

// Filtro de mensagens antigas (mais de 5 minutos atrás - ex: reconexão do WhatsApp)
const msgTs = Number(dados.messageTimestamp || 0);
const nowTs = Math.floor(Date.now() / 1000);
const isOldMessage = msgTs > 0 && (nowTs - msgTs) > 300;

if (isOldMessage) {
  return [{
    json: {
      ...dados,
      botAtivo: false,
      mensagemAntiga: true,
      comandoAdmin: '',
      msgRespostaAdmin: ''
    }
  }];
}

// Exclusivo para o número do Guilherme
const guilhermeNums = ['5511989568771', '11989568771'];
const isGuilherme = guilhermeNums.some(num =>
  (dados.remoteJid || '').includes(num) || (dados.senderNumber || '').includes(num)
);
const isFromMe = dados.fromMe === true || dados.fromMe === 'true';
const text = String(dados.conversation || '').trim().toLowerCase();

let comandoAdmin = '';
let msgRespostaAdmin = '';

if (isGuilherme && !isFromMe && (dados.messageType === 'conversation' || dados.messageType === 'extendedTextMessage')) {
  if (text === 'desativar' || text === 'pausar' || text === 'desligar') {
    staticData.botAtivo = false;
    comandoAdmin = 'desativar';
    msgRespostaAdmin = '⏸️ *Portuguinha DESATIVADO, patrão!* 🛑🇵🇹\n\nEntrei em modo silencioso e não vou responder clientes nem processar pedidos até você mandar *ativar* aqui para mim!';
  } else if (text === 'ativar' || text === 'ligar') {
    staticData.botAtivo = true;
    comandoAdmin = 'ativar';
    msgRespostaAdmin = '▶️ *Portuguinha ATIVADO e nos trinques, patrão!* 🚗🇵🇹✨\n\nJá estou de volta atendendo os clientes e anotando os carros do pátio a todo vapor! 🧼💨';
  } else if (text === 'status') {
    comandoAdmin = 'status';
    msgRespostaAdmin = staticData.botAtivo
      ? '🟢 *Status do Portuguinha:* Estou *ATIVADO* e trabalhando nos trinques, patrão! 🚗🇵🇹✨\n_(Mande *desativar* se quiser me pausar)_'
      : '🔴 *Status do Portuguinha:* Estou *DESATIVADO* (em pausa), patrão! ⏸️\n_(Mande *ativar* quando quiser me ligar de novo)_';
  }
}

return [{
  json: {
    ...dados,
    botAtivo: staticData.botAtivo,
    mensagemAntiga: false,
    comandoAdmin,
    msgRespostaAdmin
  }
}];

const staticData = $getWorkflowStaticData('global');

// Obter a data de hoje no formato YYYY-MM-DD (fuso horário de São Paulo)
const now = new Date();
const spTime = new Date(now.toLocaleString('en-US', { timeZone: 'America/Sao_Paulo' }));
const year = spTime.getFullYear();
const month = String(spTime.getMonth() + 1).padStart(2, '0');
const day = String(spTime.getDate()).padStart(2, '0');
const hojeStr = `${year}-${month}-${day}`;

// Se já enviou o aviso de inicialização hoje, bloqueia e não envia nada (retorna array vazio)
if (staticData.ultimoAvisoInicializacao === hojeStr) {
  return [];
}

// Primeira inicialização do dia: registra a data e libera o envio
staticData.ultimoAvisoInicializacao = hojeStr;

return [{
  json: {
    primeiraInicializacaoDoDia: true,
    dataHoje: hojeStr
  }
}];
